// Accept a raw JSON post or a form-encoded submission and flatten both into
// one shape, so downstream nodes only handle one field layout.
const incoming = $input.first().json;
const body = incoming.body ?? incoming;

const str = (v) => (typeof v === 'string' ? v.trim() : v == null ? '' : String(v).trim());

const lead = {
  firstName: str(body.firstName ?? body.first_name ?? body.fname),
  lastName:  str(body.lastName  ?? body.last_name  ?? body.lname),
  email:     str(body.email ?? body.email_address).toLowerCase(),
  phone:     str(body.phone ?? body.phone_number),
  company:   str(body.company ?? body.organisation ?? body.organization),
  message:   str(body.message ?? body.notes ?? body.comments),
  source:    str(body.source) || 'webhook',
  budget:    str(body.budget),
  website:   str(body.website),
};

const errors = [];
const warnings = [];

// Permissive on purpose: catches obvious junk without rejecting valid
// addresses that a strict RFC pattern would.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
if (!lead.email) {
  errors.push('email is required');
} else if (!EMAIL_RE.test(lead.email)) {
  errors.push('email is not a valid address');
}

if (!lead.firstName && !lead.lastName && !lead.company) {
  errors.push('need at least a first name, last name or company');
}

// A bad phone number is dropped with a warning rather than failing the lead.
let phone = lead.phone.replace(/[^\d+]/g, '');
if (phone && !phone.startsWith('+')) {
  phone = '+' + phone.replace(/^0+/, '');
}
if (phone && phone.replace(/\D/g, '').length < 7) {
  warnings.push('phone discarded, too short to be a real number');
  phone = '';
}
lead.phone = phone;

// Idempotency key so a retried webhook does not create a second contact.
// Falls back to the email address when the caller does not supply one.
const idempotencyKey = str(body.idempotencyKey ?? body.idempotency_key) || lead.email;

return [{
  json: {
    valid: errors.length === 0,
    errors,
    warnings,
    idempotencyKey,
    receivedAt: new Date().toISOString(),
    lead,
  },
}];

// Resolve custom field names to GHL ids at runtime. Hardcoded ids would tie
// the export to one sub-account; this costs one API call per run instead.
const upstream = $('Validate & Normalise').first().json;
const fields = $input.first().json.customFields ?? [];

const byName = {};
for (const f of fields) {
  if (f && f.name) byName[f.name.trim().toLowerCase()] = f.id;
}

const WANTED = {
  score:     'ai lead score',
  tier:      'ai qualification',
  reason:    'ai reason',
  sourceRaw: 'lead source raw',
  timestamp: 'intake timestamp',
};

const fieldIds = {};
const missing = [];
for (const [key, name] of Object.entries(WANTED)) {
  if (byName[name]) fieldIds[key] = byName[name];
  else missing.push(name);
}

// Missing fields are reported, not fatal. The contact is still created, it
// just carries less enrichment.
return [{ json: { ...upstream, fieldIds, missingFields: missing } }];

// Build the request body here rather than in the HTTP node. Lead text is
// user-supplied, and interpolating it into the node's JSON field would let a
// quote break the payload. Building an object and stringifying it will not.
const ctx = $('Build Field Map').first().json;
const lead = ctx.lead;

const search = $input.first().json;
const existing = (search.contacts ?? [])[0] ?? null;

const facts = [
  `Name: ${[lead.firstName, lead.lastName].filter(Boolean).join(' ') || 'not given'}`,
  `Email: ${lead.email}`,
  `Phone: ${lead.phone || 'not given'}`,
  `Company: ${lead.company || 'not given'}`,
  `Website: ${lead.website || 'not given'}`,
  `Stated budget: ${lead.budget || 'not given'}`,
  `Source: ${lead.source}`,
  `Returning contact: ${existing ? 'yes, already in the CRM' : 'no, first contact'}`,
  `Message: ${lead.message || 'none supplied'}`,
].join('\n');

const claudeBody = {
  model: 'claude-sonnet-5',
  max_tokens: 512,
  // Forcing the tool guarantees a parseable result. Prompting for "JSON only"
  // does not, and it fails intermittently rather than obviously.
  tool_choice: { type: 'tool', name: 'record_qualification' },
  tools: [{
    name: 'record_qualification',
    description: 'Record the qualification verdict for one inbound sales lead.',
    input_schema: {
      type: 'object',
      properties: {
        score: {
          type: 'integer',
          description: 'Buying intent from 0 to 100.',
        },
        tier: {
          type: 'string',
          enum: ['Hot', 'Warm', 'Cold'],
          description: 'Hot: clear need and budget signal. Warm: real interest, detail missing. Cold: vague, off-topic or likely spam.',
        },
        reason: {
          type: 'string',
          description: 'One or two sentences a salesperson can read before calling. Cite what in the lead drove the verdict.',
        },
        suggested_action: {
          type: 'string',
          description: 'The single next step for the rep.',
        },
      },
      required: ['score', 'tier', 'reason', 'suggested_action'],
    },
  }],
  messages: [{
    role: 'user',
    content:
      'You are qualifying an inbound lead for a B2B services business. ' +
      'Judge only what is here; do not invent context. A sparse enquiry from a ' +
      'real company outranks a long message with no company behind it.\n\n' +
      '<lead>\n' + facts + '\n</lead>',
  }],
};

return [{
  json: {
    ...ctx,
    existingContactId: existing ? existing.id : null,
    isDuplicate: Boolean(existing),
    claudeBody,
  },
}];

const ctx = $('Prepare Qualification Prompt').first().json;
const res = $input.first().json;

const block = (res.content ?? []).find((c) => c.type === 'tool_use');
if (!block || !block.input) {
  throw new Error('Claude returned no qualification tool call: ' + JSON.stringify(res).slice(0, 400));
}

const q = block.input;
const tiers = ['Hot', 'Warm', 'Cold'];

// Clamp regardless of the schema, in case the value comes back out of range.
const score = Math.max(0, Math.min(100, Number(q.score) || 0));
const tier = tiers.includes(q.tier) ? q.tier : (score >= 70 ? 'Hot' : score >= 40 ? 'Warm' : 'Cold');

const lead = ctx.lead;
const fieldIds = ctx.fieldIds ?? {};

const customFields = [];
const put = (key, value) => {
  if (fieldIds[key] && value !== '' && value != null) {
    customFields.push({ id: fieldIds[key], value: String(value) });
  }
};
put('score', score);
put('tier', tier);
put('reason', q.reason ?? '');
put('sourceRaw', lead.source);
put('timestamp', ctx.receivedAt);

const contact = {
  locationId: $env.GHL_LOCATION_ID,
  email: lead.email,
  source: lead.source,
  tags: ['inbound-lead', `ai-${tier.toLowerCase()}`],
  customFields,
};
if (lead.firstName) contact.firstName = lead.firstName;
if (lead.lastName) contact.lastName = lead.lastName;
if (lead.phone) contact.phone = lead.phone;
if (lead.company) contact.companyName = lead.company;

return [{
  json: {
    ...ctx,
    qualification: { score, tier, reason: q.reason ?? '', suggestedAction: q.suggested_action ?? '' },
    contact,
  },
}];

const ctx = $('Parse Qualification').first().json;
const upsert = $input.first().json;

const contactId = upsert.contact?.id ?? upsert.id ?? ctx.existingContactId;
if (!contactId) {
  throw new Error('CRM upsert returned no contact id: ' + JSON.stringify(upsert).slice(0, 400));
}

const lead = ctx.lead;
const q = ctx.qualification;
const greeting = lead.firstName ? `Hi ${lead.firstName},` : 'Hi,';

const html = [
  `<p>${greeting}</p>`,
  '<p>Thanks for getting in touch. Your enquiry has landed with us and someone will come back to you shortly.</p>',
  lead.message ? `<p>For your records, this is what you sent:</p><blockquote>${lead.message.replace(/</g, '&lt;')}</blockquote>` : '',
  '<p>Best,<br/>The team</p>',
].filter(Boolean).join('\n');

return [{
  json: {
    ...ctx,
    contactId,
    emailBody: {
      type: 'Email',
      contactId,
      subject: 'We received your enquiry',
      html,
    },
    opportunityBody: {
      locationId: $env.GHL_LOCATION_ID,
      pipelineId: $env.GHL_PIPELINE_ID,
      contactId,
      name: `${lead.company || [lead.firstName, lead.lastName].filter(Boolean).join(' ') || lead.email} - inbound`,
      status: 'open',
      monetaryValue: 0,
    },
    telegramText: [
      `<b>New ${q.tier.toUpperCase()} lead</b> (score ${q.score}/100)`,
      '',
      `<b>${[lead.firstName, lead.lastName].filter(Boolean).join(' ') || 'Name not given'}</b>`,
      lead.company ? `Company: ${lead.company}` : '',
      `Email: ${lead.email}`,
      lead.phone ? `Phone: ${lead.phone}` : '',
      '',
      `<i>${q.reason}</i>`,
      '',
      `Next step: ${q.suggestedAction}`,
      ctx.isDuplicate ? '\n(returning contact, record updated not duplicated)' : '',
    ].filter(Boolean).join('\n'),
  },
}];

// Reached when the CRM write fails. The lead is already validated and scored,
// so it is sent on to Telegram rather than dropped.
const err = $input.first().json;
const ctx = $('Parse Qualification').first().json;

return [{
  json: {
    lead: ctx.lead,
    qualification: ctx.qualification,
    error: err.error?.message ?? err.message ?? JSON.stringify(err).slice(0, 300),
    telegramText: [
      '<b>LEAD CAPTURE FAILED</b>',
      '',
      `The CRM write did not go through for <b>${ctx.lead.email}</b>.`,
      'The lead is in this message so it is not lost. Add it by hand.',
      '',
      `Name: ${[ctx.lead.firstName, ctx.lead.lastName].filter(Boolean).join(' ') || 'not given'}`,
      `Company: ${ctx.lead.company || 'not given'}`,
      `Phone: ${ctx.lead.phone || 'not given'}`,
      `Message: ${ctx.lead.message || 'none'}`,
      '',
      `Error: ${err.error?.message ?? err.message ?? 'unknown'}`,
    ].join('\n'),
  },
}];
